<?php
namespace App\Services;
use Carbon\CarbonImmutable as Date;
use Illuminate\Support\Facades\Http;
final class SubscriptionRenewal {
 public static function change(bool $renew):array {
  $store=app(SalonStore::class);$state=$store->read();$sub=$state['subscription'];abort_unless(PlatformAccess::mode($state)==='active',422,'Az üzemeltető által kezelt hozzáférésnél nincs automatikus havidíj.');$cancelAt=null;$id=$sub['id']??null;if(!$id&&!$renew&&!empty($sub['cancelAt']))return ['renewalEnabled'=>false,'cancelAt'=>$sub['cancelAt'],'stripe'=>false];
  if($id){$key=config('integrations.platform_stripe.key');abort_unless($key,422,'A központi Stripe-kapcsolat hiányzik.');try{$current=Http::timeout(15)->withToken($key)->get('https://api.stripe.com/v1/subscriptions/'.rawurlencode($id))->throw()->json();abort_unless(($current['id']??null)===$id,422);abort_if($renew&&in_array($current['status']??'',['canceled','incomplete_expired'],true),422,'Ez az előfizetés már megszűnt. Újraindításhoz indíts új bankkártyás előfizetést.');$result=Http::timeout(20)->withToken($key)->asForm()->post('https://api.stripe.com/v1/subscriptions/'.rawurlencode($id),['cancel_at_period_end'=>$renew?'false':'true'])->throw()->json();abort_unless(($result['id']??null)===$id&&(!empty($result['cancel_at_period_end'])===!$renew),422,'A Stripe nem igazolta a módosítást.');$end=$result['cancel_at']??$result['current_period_end']??$result['items']['data'][0]['current_period_end']??null;$cancelAt=$end?Date::createFromTimestamp($end)->toISOString():null;abort_if(!$renew&&!$cancelAt,422,'A Stripe nem adta meg a megszűnés időpontját.');}catch(\Illuminate\Http\Client\HttpClientException $e){SystemIssues::capture($e,'subscription',app(Tenant::class)->id);throw new \InvalidArgumentException('A Stripe-válasz nem igazolható. Ellenőrizd az előfizetést; ne indíts új párhuzamos fizetést.');}}
  else{$cancelAt=Subscriptions::nextPeriod($state);if(!$renew&&Date::parse($sub['paidUntil']??now())->isFuture())$cancelAt=$sub['paidUntil'];if(!$renew&&!empty($sub['trialEndsAt'])&&Date::parse($sub['trialEndsAt'])->isFuture())$cancelAt=$sub['trialEndsAt'];}
  $store->mutate(function(&$s)use($renew,$cancelAt,$id){abort_unless(($s['subscription']['id']??null)===$id,409,'Az előfizetés közben megváltozott.');if($renew&&!empty($s['subscription']['cancelAt'])&&Date::parse($s['subscription']['cancelAt'])->lte(now()))$s['subscription']['billingRestartAt']=now()->toISOString();$s['subscription']['renewalEnabled']=$renew;$s['subscription']['cancelAt']=$renew?null:$cancelAt;$s['subscription']['cancellationRequestedAt']=$renew?null:now()->toISOString();foreach($s['subscription']['charges']??[] as $i=>$charge)if(($charge['waivedReason']??'')==='subscription_cancelled'&&$renew&&Date::parse($charge['from'])->gte(now())){$s['subscription']['charges'][$i]['status']='pending';unset($s['subscription']['charges'][$i]['waivedReason']);}Subscriptions::refresh($s);});return ['renewalEnabled'=>$renew,'cancelAt'=>$renew?null:$cancelAt,'stripe'=>(bool)$id];
 }
}
